                            next_state     = ST_IDLE;
                        end
                        else begin
                            next_state     = ST_ERROR;
                        end
                    end

                    default: begin
                        // Should never happen; default to IDLE
                        next_state = ST_IDLE;
                    end
                endcase
            end
        end
    end

endmodule

